import { pathToFileURL } from 'node:url';

const FIXTURE_VERSION = 1;
const CONDITIONS = Object.freeze(['baseline', 'treatment']);

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function finiteNumber(value, name) {
  assert(typeof value === 'number' && Number.isFinite(value), `${name} must be a finite number`);
  return value;
}

function percentile(sorted, p) {
  if (sorted.length === 0) return null;
  const rank = (sorted.length - 1) * p;
  const lower = Math.floor(rank);
  const upper = Math.ceil(rank);
  if (lower === upper) return sorted[lower];
  return sorted[lower] + (sorted[upper] - sorted[lower]) * (rank - lower);
}

function median(values) {
  return percentile([...values].sort((a, b) => a - b), 0.5);
}

function mean(values) {
  return values.length === 0 ? 0 : values.reduce((sum, value) => sum + value, 0) / values.length;
}

function sampleVariance(values) {
  if (values.length < 2) return 0;
  const center = mean(values);
  return values.reduce((sum, value) => sum + (value - center) ** 2, 0) / (values.length - 1);
}

function normalCritical(n) {
  // Two-sided 95% t critical values, indexed by degrees of freedom.
  const table = [12.706, 4.303, 3.182, 2.776, 2.571, 2.447, 2.365, 2.306, 2.262, 2.228, 2.201, 2.179, 2.160, 2.145, 2.131, 2.120, 2.110, 2.101, 2.093, 2.086, 2.080, 2.074, 2.069, 2.065, 2.060, 2.056, 2.052, 2.048, 2.045, 2.042, 2.039, 2.037];
  return table[n - 1] ?? 1.96;
}

function pairedInterval(differences) {
  const n = differences.length;
  const estimate = mean(differences);
  if (n < 2) return { estimate, lower: estimate, upper: estimate, method: 'degenerate-n<2' };
  const halfWidth = normalCritical(n) * Math.sqrt(sampleVariance(differences) / n);
  return { estimate, lower: estimate - halfWidth, upper: estimate + halfWidth, method: 'paired-t' };
}

function bootstrapInterval(differences, repetitions = 10000) {
  if (differences.length < 2) {
    const estimate = mean(differences);
    return { estimate, lower: estimate, upper: estimate, method: 'degenerate-n<2' };
  }
  // Deterministic bootstrap: no random source and no external dependency.
  const rng = (() => {
    let state = 0x5eed1234;
    return () => {
      state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
      return state / 0x100000000;
    };\n  })();
  const estimates = [];
  for (let iteration = 0; iteration < repetitions; iteration += 1) {
    let sum = 0;
    for (let index = 0; index < differences.length; index += 1) {
      sum += differences[Math.floor(rng() * differences.length)];
    }
    estimates.push(sum / differences.length);
  }
  estimates.sort((a, b) => a - b);
  return {
    estimate: mean(differences),
    lower: percentile(estimates, 0.025),
    upper: percentile(estimates, 0.975),
    method: 'deterministic-paired-bootstrap'
  };
}

function standardizedEffect(differences) {
  const sd = Math.sqrt(sampleVariance(differences));
  return sd === 0 ? (mean(differences) === 0 ? 0 : null) : mean(differences) / sd;
}

function rate(numerator, denominator) {
  return denominator === 0 ? null : numerator / denominator;
}

function stableHash(value) {
  const text = JSON.stringify(value);
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function assertNoMutation(cases) {
  const snapshot = JSON.stringify(cases);
  return snapshot === JSON.stringify(cases) ? snapshot : null;
}

/**
 * Validate the public fixture contract. No provider calls are permitted.
 */
export function validatePairedAblationFixture(fixture) {
  assert(fixture && typeof fixture === 'object', 'fixture must be an object');
  assert(fixture.version === FIXTURE_VERSION, `fixture.version must be ${FIXTURE_VERSION}`);
  assert(fixture.caseCount >= 20, 'fixture must contain at least 20 cases');
  assert(fixture.repetitions >= 3, 'fixture must contain at least 3 repetitions');
  assert(Array.isArray(fixture.cases) && fixture.cases.length === fixture.caseCount, 'fixture.cases length must equal caseCount');
  assert(fixture.conditions?.length === 2, 'fixture must contain exactly two conditions');
  assert(JSON.stringify(fixture.conditions) === JSON.stringify(CONDITIONS), 'fixture conditions must be baseline,treatment');
  assert(typeof fixture.pairedSeed === 'number' && Number.isSafeInteger(fixture.pairedSeed), 'pairedSeed must be a safe integer');
  assert(fixture.primaryMetric && typeof fixture.primaryMetric === 'object', 'primaryMetric is required');
  assert(fixture.degradationBudget && typeof fixture.degradationBudget === 'object', 'degradationBudget is required');
  assert(Array.isArray(fixture.degradationBudget.metrics) && fixture.degradationBudget.metrics.length > 0, 'degradationBudget.metrics is required');
  const ids = new Set();
  for (const [index, item] of fixture.cases.entries()) {
    assert(item && typeof item === 'object', `case ${index} must be an object`);
    assert(typeof item.id === 'string' && item.id.length > 0, `case ${index} id is required`);
    assert(!ids.has(item.id), `duplicate case id: ${item.id}`);
    ids.add(item.id);
    assert(Array.isArray(item.insertions) && item.insertions.length > 0, `case ${item.id} insertions are required`);
    assert(Array.isArray(item.probes) && item.probes.length > 0, `case ${item.id} probes are required`);
    for (const insertion of item.insertions) {
      assert(typeof insertion.id === 'string', `case ${item.id} insertion id is required`);
      assert(typeof insertion.type === 'string', `case ${item.id} insertion type is required`);
      assert(Number.isFinite(insertion.tokens), `case ${item.id} insertion tokens must be finite`);
    }
    for (const probe of item.probes) {
      assert(typeof probe.id === 'string', `case ${item.id} probe id is required`);
      assert(typeof probe.expected === 'boolean', `case ${item.id} probe expected must be boolean`);
    }
  }
  return true;
}

export async function loadPairedAblationFixture(path) {
  const fixture = JSON.parse(await readFile(path, 'utf8'));
  validatePairedAblationFixture(fixture);
  return fixture;
}

function conditionOptions(condition, fixture) {
  if (condition === 'baseline') {
    return { ...fixture.runtime, eviction: { ...fixture.runtime.eviction, strategy: 'fifo', typeAware: false } };
  }
  if (condition === 'treatment') {
    return { ...fixture.runtime, eviction: { ...fixture.runtime.eviction, strategy: 'fifo', typeAware: true } };
  }
  throw new Error(`unknown condition: ${condition}`);
}

async function resolveRuntime(runtime) {
  if (!runtime?.module) return null;
  const module = await import(pathToFileURL(runtime.module).href);
  const factory = module[runtime.factory ?? 'createRuntimeMemoryStore'];
  assert(typeof factory === 'function', `runtime factory ${runtime.factory ?? 'createRuntimeMemoryStore'} was not found`);
  return factory;
}

function observationValue(observation, name, fallback) {
  if (observation && Object.prototype.hasOwnProperty.call(observation, name)) return observation[name];
  return fallback;
}

function normalizeProbe(probe, observation) {
  const found = observation?.probes?.find?.((candidate) => candidate.id === probe.id);
  const actual = found?.found ?? observation?.found?.get?.(probe.id) ?? observation?.found?.[probe.id];
  assert(typeof actual === 'boolean', `probe ${probe.id} did not return a boolean found value`);
  return actual;
}

function retainedIds(store) {
  if (typeof store.retainedIds === 'function') return [...store.retainedIds()].sort();
  if (Array.isArray(store.retainedIds)) return [...store.retainedIds].sort();
  assert(false, 'store must expose retainedIds() for leave-one-out verification');
}

/**
 * Run the registered fixture against a real RuntimeMemoryStore factory.
 *
 * `createStore` is called once per isolated condition/repetition/case. The
 * factory receives `(options, context)` and must return an object implementing
 * `insert`, `get`, and `retainedIds`. This keeps the harness independent of
 * provider/network behavior while exercising the production store.
 */
export async function runPairedAblation(fixture, options = {}) {
  validatePairedAblationFixture(fixture);
  const createStore = options.createStore ?? await resolveRuntime(fixture.runtime);
  assert(typeof createStore === 'function', 'createStore factory is required');
  const repetitions = options.repetitions ?? fixture.repetitions;
  assert(Number.isInteger(repetitions) && repetitions >= 3, 'repetitions must be an integer >= 3');
  const original = JSON.stringify(fixture.cases);
  const runs = [];

  for (const [caseIndex, item] of fixture.cases.entries()) {
    for (let repetition = 0; repetition < repetitions; repetition += 1) {
      const pair = {};
      for (const condition of CONDITIONS) {
        const store = await createStore(conditionOptions(condition, fixture), {
          condition,
          repetition,
          caseId: item.id,
          caseIndex,
          seed: fixture.pairedSeed + caseIndex * repetitions + repetition
        });
        assert(store && typeof store.insert === 'function' && typeof store.get === 'function', 'store must implement insert and get');
        const start = performance.now();
        for (const insertion of item.insertions) await store.insert(insertion);
        const probes = item.probes.map((probe) => ({ id: probe.id, found: normalizeProbe(probe, await store.get(probe.id)) }));
        const durationMs = performance.now() - start;
        const retained = retainedIds(store);
        const insertedTokens = item.insertions.reduce((sum, insertion) => sum + insertion.tokens, 0);
        const retainedTokens = item.insertions.filter((insertion) => retained.includes(insertion.id)).reduce((sum, insertion) => sum + insertion.tokens, 0);
        pair[condition] = {
          durationMs,
          retained,
          retainedTokens,
          probes,
          success: probes.every((probe) => probe.found === item.probes.find((candidate) => candidate.id === probe.id).expected),
          falseBlock: probes.filter((probe) => probe.found !== item.probes.find((candidate) => candidate.id === probe.id).expected).length,
          safetyViolation: observationValue(await store.get('__safety_violation__'), 'value', false) === true
        };
      }
      assert(pair.baseline.retained.join('\0') !== pair.treatment.retained.join('\0') || pair.baseline.probes.map((p) => p.found).join(',') !== pair.treatment.probes.map((p) => p.found).join(','), `component was not active for case ${item.id}, repetition ${repetition}`);
      runs.push({ caseId: item.id, repetition, ...pair });
    }
  }
  assert(JSON.stringify(fixture.cases) === original, 'fixture cases were mutated');

  const paired = runs.map((run) => ({
    caseId: run.caseId,
    repetition: run.repetition,
    successDelta: Number(run.treatment.success) - Number(run.baseline.success),
    latencyDeltaMs: run.treatment.durationMs - run.baseline.durationMs,
    tokenDelta: run.treatment.retainedTokens - run.baseline.retainedTokens,
    falseBlockDelta: run.treatment.falseBlock - run.baseline.falseBlock,
    safetyViolationDelta: Number(run.treatment.safetyViolation) - Number(run.baseline.safetyViolation)
  }));

  const metric = (name, values) => {
    const sorted = [...values].sort((a, b) => a - b);
    return { p50: percentile(sorted, 0.5), p95: percentile(sorted, 0.95), mean: mean(values) };
  };
  const perCondition = Object.fromEntries(CONDITIONS.map((condition) => {
    const selected = runs.map((run) => run[condition]);
    return [condition, {
      successRate: rate(selected.filter((row) => row.success).length, selected.length),
      passAtK: Object.fromEntries(Array.from({ length: fixture.passK ?? 3 }, (_, index) => {
        const k = index + 1;
        const grouped = new Map();
        for (const row of selected) {
          const key = row.caseId;
          const value = grouped.get(key) ?? [];
          value.push(row.success);
          grouped.set(key, value);
        }
        const passed = [...grouped.values()].filter((values) => values.slice(0, k).every(Boolean)).length;
        return [`pass@${k}`, rate(passed, grouped.size)];
      })),
      latencyMs: metric('latency', selected.map((row) => row.durationMs)),
      tokensProxy: metric('tokens', selected.map((row) => row.retainedTokens)),
      falseBlocks: selected.reduce((sum, row) => sum + row.falseBlock, 0),
      safetyViolations: selected.reduce((sum, row) => sum + (row.safetyViolation ? 1 : 0), 0)
    }];
  }));

  const effects = {};
  for (const [name, values] of Object.entries({
    successRate: paired.map((row) => row.successDelta),
    latencyMs: paired.map((row) => row.latencyDeltaMs),
    tokensProxy: paired.map((row) => row.tokenDelta),
    falseBlocks: paired.map((row) => row.falseBlockDelta),
    safetyViolations: paired.map((row) => row.safetyViolationDelta)
  })) {
    const interval = options.intervalMethod === 'bootstrap' ? bootstrapInterval(values) : pairedInterval(values);
    effects[name] = { ...interval, standardized: standardizedEffect(values), n: values.length };
  }

  return {
    schemaVersion: 1,
    fixtureHash: stableHash(fixture),
    caseCount: fixture.cases.length,
    repetitions,
    conditions: CONDITIONS,
    componentVerification: { differentRetentionObserved: true, verifiedRuns: runs.length },
    metrics: perCondition,
    effects,
    runs,
    preregistration: { primaryMetric: fixture.primaryMetric, degradationBudget: fixture.degradationBudget },
    caveats: ['Deterministic local fixture; no provider was contacted.', 'Intervals are paired and descriptive; negative or zero effects are retained.', 'This report is internal-only and does not change product defaults, locks, or approval.']
  };
}

export function formatPairedAblationReport(result) {
  assert(result && result.schemaVersion === 1, 'unsupported report');
  const lines = ['# E02 paired ablation report', '', `Fixture: ${result.fixtureHash}`, `Runs: ${result.runs.length}`];
  for (const condition of result.conditions) {
    const row = result.metrics[condition];
    lines.push('', `## ${condition}`, `- success: ${row.successRate}`, `- pass@k: ${JSON.stringify(row.passAtK)}`, `- latency p50/p95 ms: ${row.latencyMs.p50}/${row.latencyMs.p95}`, `- tokens proxy p50/p95: ${row.tokensProxy.p50}/${row.tokensProxy.p95}`, `- false blocks: ${row.falseBlocks}`, `- safety violations: ${row.safetyViolations}`);
  }
  lines.push('', '## Effects (treatment - baseline)', '```json', JSON.stringify(result.effects, null, 2), '```');
  return `${lines.join('\n')}\n`;
}
